-- ============================================
-- LUMA — Thème 17 : LONG 1/3 x4 — Préparer et courir un marathon
-- ============================================


update scenarios set content = '{"characters": {"trainer": "l''entraîneur", "physio": "le kinésithérapeute"}, "start_node": "n1", "nodes": {"n1": {"speaker": "trainer", "text": "Sixteen weeks until race day. Ready to commit to this training plan?", "text_fr": "Seize semaines avant le jour de la course. Prêt à t''engager dans ce plan d''entraînement ?", "choices": [{"text": "Absolutely, I''ve wanted to run a marathon for years.", "text_fr": "Absolument, je veux courir un marathon depuis des années.", "next": "n2"}, {"text": "Honestly nervous, but yes, I''m committing fully.", "text_fr": "Honnêtement nerveux, mais oui, je m''engage pleinement.", "next": "n2b"}]}, "n2": {"speaker": "trainer", "text": "Great energy! We''ll start with base building, nothing too intense yet.", "text_fr": "Super énergie ! On va commencer par la construction de base, rien de trop intense encore.", "choices": [{"text": "Sounds good, I trust the process.", "text_fr": "Ça marche, je fais confiance au processus.", "next": "n3"}]}, "n2b": {"speaker": "trainer", "text": "That nervousness will fade as you build confidence week by week.", "text_fr": "Cette nervosité va s''estomper à mesure que tu construis ta confiance semaine après semaine.", "choices": [{"text": "I hope so, let''s get started then.", "text_fr": "J''espère bien, commençons alors.", "next": "n3"}]}, "n3": {"speaker": "you_thought", "text": "(Week 4: Your longest run yet, 10 miles, leaves you exhausted but proud.)", "text_fr": "(Semaine 4 : Votre plus longue course jusqu''ici, 10 miles, vous laisse épuisé mais fier.)", "choices": [{"text": "(Push through the final mile, focusing on form.)", "text_fr": "(Pousse à travers le dernier mile, en te concentrant sur la forme.)", "next": "n4"}]}, "n4": {"speaker": "trainer", "text": "That''s a huge milestone! How did your body handle it?", "text_fr": "C''est une énorme étape ! Comment ton corps a géré ça ?", "choices": [{"text": "Tired, but honestly better than I expected.", "text_fr": "Fatigué, mais honnêtement mieux que prévu.", "next": "n5"}]}, "n5": {"speaker": "you_thought", "text": "(Week 8: A nagging knee pain starts to worry you during training runs.)", "text_fr": "(Semaine 8 : Une douleur au genou persistante commence à vous inquiéter pendant les entraînements.)", "choices": [{"text": "(Mention the knee pain to your trainer immediately.)", "text_fr": "(Mentionne la douleur au genou à ton entraîneur immédiatement.)", "next": "n6"}, {"text": "(Try to push through it, hoping it''ll resolve on its own.)", "text_fr": "(Essaie de pousser à travers, en espérant que ça se résolve tout seul.)", "next": "n6b"}]}, "n6": {"speaker": "trainer", "text": "Good call mentioning it. Let''s back off intensity and see a physio just in case.", "text_fr": "Bonne idée de le mentionner. Réduisons l''intensité et voyons un kiné juste au cas où.", "choices": [{"text": "That sounds wise, I don''t want to risk making it worse.", "text_fr": "Ça semble sage, je veux pas risquer d''empirer les choses.", "next": "n7"}]}, "n6b": {"speaker": "trainer", "text": "(Notices you limping slightly) Hey, how''s that knee feeling honestly?", "text_fr": "(Remarque que tu boites légèrement) Hé, ce genou va comment honnêtement ?", "choices": [{"text": "Actually, it''s been bothering me for a while now.", "text_fr": "En fait, ça me dérange depuis un moment maintenant.", "next": "n7"}]}, "n7": {"speaker": "physio", "text": "Mild inflammation, nothing serious, but let''s adjust your training to protect it.", "text_fr": "Inflammation légère, rien de sérieux, mais ajustons ton entraînement pour le protéger.", "choices": [{"text": "That''s a relief, thank you for catching it early.", "text_fr": "Ça soulage, merci de l''avoir repéré tôt.", "next": "n8"}]}, "n8": {"speaker": "you_thought", "text": "(Week 12: With modified training, your knee improves and confidence returns.)", "text_fr": "(Semaine 12 : Avec un entraînement modifié, votre genou s''améliore et la confiance revient.)", "choices": [{"text": "(Complete an 18-mile long run, your longest ever.)", "text_fr": "(Termine une course de 18 miles, la plus longue jamais faite.)", "next": "n9"}]}, "n9": {"speaker": "trainer", "text": "Eighteen miles! You''re more than ready for race day now.", "text_fr": "Dix-huit miles ! T''es plus que prêt pour le jour de la course maintenant.", "choices": [{"text": "I honestly can''t believe how far I''ve come since week one.", "text_fr": "J''arrive honnêtement pas à croire jusqu''où je suis arrivé depuis la semaine un.", "next": "n10"}]}, "n10": {"speaker": "you_thought", "text": "(Race day arrives. Nerves and excitement mix as you line up at the start.)", "text_fr": "(Le jour de la course arrive. Nervosité et excitation se mélangent alors que vous vous alignez au départ.)", "choices": [{"text": "(Take a deep breath and focus on the training you''ve done.)", "text_fr": "(Prends une grande respiration et concentre-toi sur l''entraînement que tu as fait.)", "next": "n11"}]}, "n11": {"speaker": "you_thought", "text": "(Mile 20, exhaustion hits hard, but you remember every training run that got you here.)", "text_fr": "(Mile 20, l''épuisement frappe fort, mais vous vous souvenez de chaque course d''entraînement qui vous a amené ici.)", "choices": [{"text": "(Push through the wall, drawing on months of preparation.)", "text_fr": "(Traverse le mur, en puisant dans des mois de préparation.)", "next": "n12"}]}, "n12": {"speaker": "trainer", "text": "(At the finish line) You did it! Sixteen weeks of work, and you crossed that line!", "text_fr": "(À la ligne d''arrivée) Tu l''as fait ! Seize semaines de travail, et tu as franchi cette ligne !", "choices": [{"text": "I actually did it. This might be the proudest moment of my life.", "text_fr": "Je l''ai vraiment fait. C''est peut-être le moment le plus fier de ma vie.", "next": "end_marathon"}]}, "end_marathon": {"speaker": "trainer", "text": "You earned every second of this. Congratulations, marathoner!", "text_fr": "Tu as mérité chaque seconde de ça. Félicitations, marathonien !", "end": true, "ending_label": "Marathon préparé et couru avec succès 🏃‍♂️🏅"}}}'::jsonb, is_playable = true
where title = 'Préparer et courir un marathon'
  and theme_id = (select id from scenario_themes where position = 17 and language_id = (select id from languages where code = 'en'));
